export const prodT = (lang: string) => translator(PROD_EN, PROD_TRANSLATIONS, lang);
/** A shift, status, measure or reason in the person's language; anything not listed stays as it is. */
export function termT(lang: string) {
  const tr = translator(TERMS_EN, TERMS_TRANSLATIONS, lang);
  return (text: string) => (text in TERMS_EN ? tr(text as keyof typeof TERMS_EN) : text);
}
